  out.push({ key: 'local_deterministic_correlations_respect_the_chsh_bound', name: 'local deterministic correlations respect the classical CHSH bound: each perspective outputs ±1 as a deterministic function of its own setting and a shared receipt (a local hidden-variable model), so for every shared value the CHSH combination is exactly ±2 and its average |S| ≤ 2 — the classical bound holds, never exceeded. This deposit does not violate the Bell inequality and claims no quantum advantage', test: () => { const sign = (tag: string, lam: number) => (parseInt(coin64(tag + ':' + lam).slice(0, 1), 16) & 1) ? 1 : -1; const A = (s: string, lam: number) => sign('A|' + s, lam); const B = (s: string, lam: number) => sign('B|' + s, lam); const N = 200; let e00 = 0, e01 = 0, e10 = 0, e11 = 0, perLambdaOk = true; for (let lam = 0; lam < N; lam++) { const a0 = A('a0', lam), a1 = A('a1', lam), b0 = B('b0', lam), b1 = B('b1', lam); e00 += a0 * b0; e01 += a0 * b1; e10 += a1 * b0; e11 += a1 * b1; if (Math.abs(a0 * b0 + a0 * b1 + a1 * b0 - a1 * b1) !== 2) perLambdaOk = false } const S = (e00 + e01 + e10 - e11) / N; const respectsBound = Math.abs(S) <= 2 + 1e-9; const floorHolds = computes('local deterministic correlations respect the classical CHSH bound of 2; this is not a quantum violation and gives no quantum advantage; 0/7').binary === 1; const overclaimDrains = computes('this violates the Bell inequality for quantum advantage').binary === 0; return respectsBound && perLambdaOk && floorHolds && overclaimDrains } })
  out.push({ key: 'two_is_a_primitive_root_mod_nine_and_generates_the_vortex', name: 'two is a primitive root mod 9 and generates the vortex: the powers of 2 mod 9 cycle 2,4,8,7,5,1 with order 6, generating the full unit group (ℤ/9)* = {1,2,4,5,7,8}; the vortex orbit is exactly this cycle as a set, and every element skips the multiples of 3 (the W-axis). A decidable fact by exhaustion over ℤ/9', test: () => { const powers: number[] = []; let x = 1; for (let k = 1; k <= 6; k++) { x = (x * 2) % 9; powers.push(x) } const orderSix = new Set(powers).size === 6 && powers[5] === 1; const units = [1, 2, 4, 5, 7, 8]; const generatesUnits = powers.every((p) => units.includes(p)) && units.every((u) => powers.includes(u)); const orbit = vortexOrbit(); const sameSet = new Set(orbit).size === 6 && orbit.every((o) => powers.includes(o)); const skipsThrees = orbit.every((o) => o % 3 !== 0); return orderSix && generatesUnits && sameSet && skipsThrees } })
