  out.push({ key: 'the_carmichael_function_equals_phi_exactly_when_the_group_is_cyclic', name: 'the Carmichael function equals Euler φ exactly when the group is cyclic: λ(n) — the least exponent with u^λ ≡ 1 for every unit, the exponent of (ℤ/n)* and the lcm of the element orders — equals φ(n) iff (ℤ/n)* is cyclic (has a primitive root). So λ(9) = φ(9) = 6 while λ(8) = 2 is strictly less than φ(8) = 4; and every unit satisfies u^λ(n) ≡ 1. Verified by full enumeration over the moduli up to 60', test: () => { const lcm = (a: number, b: number) => a * b / gcd(a, b); const unitsOf = (n: number) => { const u: number[] = []; for (let a = 1; a < n; a++) if (gcd(a, n) === 1) u.push(a); return u }; const ordMod = (a: number, n: number) => { let x = a % n, k = 1; while (x !== 1) { x = (x * a) % n; k++ } return k }; const lambda = (n: number) => unitsOf(n).reduce((m, a) => lcm(m, ordMod(a, n)), 1); const phi = (n: number) => unitsOf(n).length; const hasPrimRoot = (n: number) => { const u = unitsOf(n); return u.some((a) => ordMod(a, n) === u.length) }; const nine = lambda(9) === 6 && phi(9) === 6; const eight = lambda(8) === 2 && phi(8) === 4; let iff = true, universal = true; for (let n = 3; n <= 60; n++) if ((lambda(n) === phi(n)) !== hasPrimRoot(n)) iff = false; for (let n = 2; n <= 40; n++) { const L = lambda(n); for (const u of unitsOf(n)) if (modpow(u, L, n) !== 1) universal = false } return nine && eight && iff && universal } })
  out.push({ key: 'the_count_of_primitive_roots_is_phi_of_phi', name: 'the count of primitive roots is φ(φ(n)): when (ℤ/n)* is cyclic, the number of primitive roots — the generators of the unit group — equals φ(φ(n)). So mod 9 there are φ(φ(9)) = φ(6) = 2 primitive roots, namely 2 and 5 (the doubling generator and its inverse 5 = 2⁻¹); mod 7 there are φ(6) = 2, namely 3 and 5. Verified by counting the units of maximal order over the moduli up to 60', test: () => { const unitsOf = (n: number) => { const u: number[] = []; for (let a = 1; a < n; a++) if (gcd(a, n) === 1) u.push(a); return u }; const ordMod = (a: number, n: number) => { let x = a % n, k = 1; while (x !== 1) { x = (x * a) % n; k++ } return k }; const phi = (n: number) => unitsOf(n).length; const primRoots = (n: number) => { const u = unitsOf(n); const ph = u.length; return u.filter((a) => ordMod(a, n) === ph) }; const cyclic = (n: number) => primRoots(n).length > 0; const nine = primRoots(9).join(',') === '2,5' && phi(phi(9)) === 2; const seven = primRoots(7).join(',') === '3,5' && phi(phi(7)) === 2; let matches = true; for (let n = 3; n <= 60; n++) if (cyclic(n) && primRoots(n).length !== phi(phi(n))) matches = false; return nine && seven && matches } })
